import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { normalizeOpenMeteoForecast as before } from './baseline-forecast.mts';
import { normalizeOpenMeteoForecast as after } from '../../supabase/functions/_shared/open-meteo-forecast.ts';
const generatedAt = '2026-09-12T00:06:00Z';
const base = Date.parse('2026-09-12T00:00:00Z') / 1000;
function fixture(point: number, iso = false) {
  const hours = Array.from({ length: 1056 }, (_, i) => base + (i - 719) * 3600);
  const time = iso ? hours.map(t => new Date(t * 1000).toISOString()) : hours;
  const atmosphere = { elevation: 700 + point * 10, hourly: { time,
    temperature_2m: hours.map((_, i) => 14 + Math.sin(i / 7) * 20),
    relative_humidity_2m: hours.map((_, i) => 60 + Math.sin(i) * 30),
    wind_speed_10m: hours.map((_, i) => 7 + (i % 5)),
    wind_gusts_10m: hours.map((_, i) => 17 + (i % 9)),
    precipitation: hours.map((_, i) => i % 37 === 0 ? 1.7 : 0),
    et0_fao_evapotranspiration: hours.map((_, i) => 0.03 + (i % 5) / 100),
  }};
  const soil = { hourly: { time, soil_moisture_3_to_9cm: hours.map((_, i) => .2 + Math.sin(i) / 20) }};
  const history = structuredClone(atmosphere);
  history.hourly.temperature_2m = hours.map((_, i) => 12 + Math.sin(i / 6) * 17);
  history.hourly.precipitation = hours.map((_, i) => i % 23 === 0 ? .9 : 0);
  return { atmosphere, soil, history };
}
const fixtures = Array.from({ length: 50 }, (_, i) => fixture(i));
for (const iso of [false, true]) {
  for (const variant of ['complete', 'gap', 'duplicate', 'cutover', 'no-history', 'short-soil', 'missing-base']) {
    const f = fixture(0, iso);
    if (variant === 'gap') f.history.hourly.temperature_2m[100] = NaN;
    if (variant === 'duplicate') f.atmosphere.hourly.time[750] = f.atmosphere.hourly.time[751];
    if (variant === 'cutover') f.history.hourly.temperature_2m[719] = NaN;
    if (variant === 'short-soil') f.soil.hourly.soil_moisture_3_to_9cm.length = 880;
    if (variant === 'missing-base') f.soil.hourly.soil_moisture_3_to_9cm.fill(NaN, 713, 720);
    const h = variant === 'no-history' ? undefined : f.history;
    assert.deepStrictEqual(after(f.atmosphere, f.soil, generatedAt, h), before(f.atmosphere, f.soil, generatedAt, h));
  }
}
function batch(fn: typeof before) {
  const start = process.cpuUsage();
  const t = performance.now();
  for (const f of fixtures) fn(f.atmosphere, f.soil, generatedAt, f.history);
  const cpu = process.cpuUsage(start);
  return { cpuMs: (cpu.user + cpu.system) / 1000, wallMs: performance.now() - t };
}
batch(before); batch(after);
const results = { parityCases: 14, pointsPerBatch: 50, before: [], after: [] } as { parityCases: number; pointsPerBatch: number; before: unknown[]; after: unknown[] };
for (let i = 0; i < 7; i++) {
  if (i % 2) { results.after.push(batch(after)); results.before.push(batch(before)); }
  else { results.before.push(batch(before)); results.after.push(batch(after)); }
}
writeFileSync(new URL('./forecast-benchmark.json', import.meta.url), JSON.stringify(results, null, 2));
console.log(JSON.stringify(results));
